function DiscoverMap({profile,back,start}){let results=profile.stats.discoverMath?.results||{};return <main className="discover-map"><Button onClick={back}><ArrowLeft/>Äventyrskartan</Button><div className="discover-head"><span>🌈</span><div><small>BYGG GRUNDEN STEG FÖR STEG</small><h1>Upptäck matte</h1><p>Bygg, jämför och hitta smarta strategier utan tidspress.</p></div></div><div className="discover-stations">{Object.entries(DISCOVER_STATIONS).map(([sid,st])=><section key={sid}><span>{st.icon}</span><h2>{st.title}</h2><p>{st.description}</p><div>{Object.entries(DISCOVER_TRACKS).map(([tid,tr])=>{let r=results[`${sid}-${tid}`];return <button key={tid} onClick={()=>start(sid,tid)}><b>{tr.icon} {tr.title}</b><small>{tr.description}</small><em>{r?`Bäst ${r.best}/6`:"Inte påbörjad"}</em></button>})}</div></section>)}</div></main>}
const DISCOVER_SKILL_NAMES={"quantity-symbol":"räkna antal","tens-ones":"tiotal och ental","number-neighbours":"talens grannar","compare-numbers":"jämföra tal","number-line":"tallinjen","even-odd":"udda och jämna tal","decompose-number":"bygga tal","sequence":"talföljder","round-tens":"närmaste tiotal","place-value":"siffrors värde","addition-within-10":"addition inom 10","friends-of-ten":"tiokamrater","doubles":"dubbelt","make-ten":"göra ett tiotal","add-tens":"addera tiotal","add-tens-ones":"tiotal och ental","near-doubles":"nästan dubbelt","addition-within-100":"addition inom 100","missing-addend":"hitta talet som saknas","word-addition":"addition i vardagen","strategy-choice":"välja strategi","reasonableness":"rimliga svar","subtract-within-10":"subtraktion inom 10","difference":"jämföra skillnad","count-up":"räkna uppåt","subtract-to-ten":"subtrahera till tio","subtract-tens":"subtrahera tiotal","inverse-relation":"sambandet plus och minus","bridge-ten-subtraction":"passera ett tiotal","subtraction-within-100":"subtraktion inom 100","missing-subtrahend":"hitta talet som saknas","word-subtraction":"subtraktion i vardagen"};
function DiscoverGame({profile,station,track,stats,back}){let qs=DISCOVER_QUESTIONS[station][track],[index,setIndex]=useState(0),[value,setValue]=useState(""),[tries,setTries]=useState(0),[records,setRecords]=useState([]),[feedback,setFeedback]=useState(null),[checkMode,setCheckMode]=useState(false),[done,setDone]=useState(false),[confidence,setConfidence]=useState(null),[reset,setReset]=useState(0),[showCanvas,setShowCanvas]=useState(false),[showHelp,setShowHelp]=useState(false),q=qs[index],target=checkMode?q.check:q;const choices=target.choices||q.choices||[];const speak=(text=target.prompt)=>{if(!("speechSynthesis" in window))return;let full=`${text}. ${choices.length?`Svar: ${choices.join(", eller ")}.`:""}`,u=new SpeechSynthesisUtterance(full);u.lang="sv-SE";u.rate=.78;u.pitch=1;speechSynthesis.cancel();speechSynthesis.speak(u)};useEffect(()=>{if(!done){let id=setTimeout(()=>speak(),350);return()=>{clearTimeout(id);speechSynthesis?.cancel?.()}}},[index,checkMode,done]);const ok=()=>String(value).trim().toLowerCase()===String(target.answer).trim().toLowerCase();const submit=()=>{if(!value)return;let right=ok();if(checkMode){setRecords(r=>[...r,{skill:q.skill,ok:right,afterSupport:true}]);setFeedback({ok:right,text:right?"Bra. Du klarade en ny uppgift.":`Rätt svar är ${target.answer}. Vi tränar mer på detta senare.`,advance:true});return}if(right){setRecords(r=>[...r,{skill:q.skill,ok:true,independent:tries===0}]);setFeedback({ok:true,text:q.explain,advance:true})}else if(tries===0){setTries(1);setShowHelp(true);setFeedback({ok:false,text:q.hint,retry:true})}else{setRecords(r=>[...r,{skill:q.skill,ok:false,support:true}]);setShowHelp(true);setFeedback({ok:false,text:`Rätt svar: ${q.answer}. ${q.explain}`,showCheck:true})}};const next=()=>{if(feedback?.retry){setFeedback(null);setValue("");return}if(feedback?.showCheck){setCheckMode(true);setFeedback(null);setValue("");setShowHelp(false);return}if(index===5){setDone(true);return}setIndex(i=>i+1);setValue("");setTries(0);setFeedback(null);setCheckMode(false);setShowHelp(false);setShowCanvas(false);setReset(x=>x+1)};useEffect(()=>{if(!done||confidence===null)return;let old=profile.stats.discoverMath||{},key=`${station}-${track}`,prev=old.results?.[key]||{},score=records.filter(r=>r.ok).length,skills={...profile.stats.learningProfile?.skills};qs.forEach(item=>{let rr=records.filter(r=>r.skill===item.skill),ind=rr.some(r=>r.independent),after=rr.some(r=>r.afterSupport&&r.ok),good=rr.some(r=>r.ok),before=skills[item.skill]||{attempts:0,independentSuccesses:0,supportSuccesses:0};skills[item.skill]={...before,attempts:(before.attempts||0)+1,independentSuccesses:(before.independentSuccesses||0)+(ind?1:0),supportSuccesses:(before.supportSuccesses||0)+(after?1:0),status:ind?"säker självständigt":after?"säker efter stöd":good?"under utveckling":"behöver återkomma",lastSeen:new Date().toISOString()}});let queue=Object.entries(skills).filter(([,x])=>x.status!=="säker självständigt").map(([skill])=>({skill,reviewAfterSessions:2}));stats(s=>({...s,xp:s.xp+score*5,discoverMath:{...old,results:{...(old.results||{}),[key]:{plays:(prev.plays||0)+1,latest:score,best:Math.max(prev.best||0,score),confidence}}},learningProfile:{...s.learningProfile,skills,reviewQueue:queue}}))},[done,confidence]);if(done&&confidence===null)return <main className="discover-confidence"><div><span>🌈</span><h1>Hur säkert kändes det?</h1><Button className="listen-button" onClick={()=>speak("Hur säkert kändes det? Välj inte säker, ganska säker eller mycket säker.")}><Volume2/> Lyssna</Button><p>Välj det som passar bäst.</p>{["Inte säker","Ganska säker","Mycket säker"].map(x=><button key={x} onClick={()=>setConfidence(x)}>{x}</button>)}</div></main>;if(done){let good=[...new Set(records.filter(r=>r.ok).map(r=>DISCOVER_SKILL_NAMES[r.skill]||r.skill))],needs=[...new Set(records.filter(r=>!r.ok||r.afterSupport).map(r=>DISCOVER_SKILL_NAMES[r.skill]||r.skill))];return <main className="discover-result"><div><span>🌟</span><small>UPPTÄCK MATTE</small><h1>{DISCOVER_STATIONS[station].title}</h1><h2>{records.filter(r=>r.ok).length} lyckade lösningar</h2><section><h3>🌟 Det här kan du</h3><p>{good.length?`Du visade att du kan ${good.slice(0,3).join(", ")}.`:"Du använde hjälpen och fortsatte tänka."}</p></section><section><h3>🌱 Nästa steg</h3><p>{needs.length?`Du får träna mer på ${needs.slice(0,3).join(", ")}.`:"Prova nästa spår när du vill."}</p></section><p><b>Så säkert kändes det:</b> {confidence}</p><Button className="primary" onClick={back}>Till Upptäck matte</Button></div></main>}let parts=target.prompt.split(/(?<=[.!?])\s+/);return <main className="discover-game"><Button onClick={back}><ArrowLeft/>Upptäck matte</Button><div className="discover-game-head"><span>{DISCOVER_STATIONS[station].icon} {DISCOVER_STATIONS[station].title}</span><b>{index+1} av 6</b></div><div className="progress"><i style={{width:`${index/6*100}%`}}/></div><div className={`discover-access-layout ${showCanvas?"with-canvas":""}`}>{showCanvas&&<section className="discover-canvas"><div className="discover-section-title"><h2><Brush/> Skrivyta</h2><Button onClick={()=>setShowCanvas(false)}>Dölj</Button></div><Canvas reset={reset}/></section>}<article className="discover-task"><small>{checkMode?"PROVA IGEN MED NYA TAL":DISCOVER_SKILL_NAMES[q.skill]?.toUpperCase()}</small><div className="discover-spoken-prompt">{parts.map((part,i)=><h1 key={i}>{part}</h1>)}</div><div className="discover-audio-tools"><Button className="listen-button" onClick={()=>speak()}><Volume2/> Lyssna igen</Button><Button onClick={()=>setShowHelp(x=>!x)}>👀 {showHelp?"Dölj hjälp":"Visa hjälp"}</Button><Button onClick={()=>setShowCanvas(x=>!x)}>✏️ {showCanvas?"Dölj skrivyta":"Visa skrivyta"}</Button></div>{!checkMode&&q.visual&&<div className="discover-visual" aria-label="Bildstöd">{q.visual}</div>}{showHelp&&<div className="discover-model"><span>👀</span><div><b>Titta så här</b><p>{q.hint}</p>{q.visual&&<strong>{q.visual}</strong>}</div></div>}{(target.type||q.type)==="choice"?<div className="discover-choices">{choices.map(x=><button key={x} className={value===x?"selected":""} onClick={()=>setValue(x)}>{x}</button>)}</div>:<input autoFocus inputMode="numeric" value={value} onChange={e=>setValue(e.target.value)} placeholder="Skriv svaret" aria-label="Skriv ditt svar"/>}<Button className="primary discover-check" disabled={!value||feedback} onClick={submit}>Kontrollera <Check/></Button>{feedback&&<div className={`discover-feedback ${feedback.ok?"right":"think"}`}><h2>{feedback.ok?"✅ Rätt!":feedback.showCheck?"📘 Nu provar du med nya tal":"💡 Titta och prova igen"}</h2><p>{feedback.text}</p><Button className="listen-button" onClick={()=>speak(feedback.text)}><Volume2/> Lyssna</Button><Button className="primary" onClick={next}>{feedback.retry?"Försök igen":feedback.showCheck?"Ny uppgift":"Fortsätt"}<ChevronRight/></Button></div>}</article></div></main>}

